const path = require('path');
const http = require('http');
const express = require('express');
const { WebSocketServer } = require('ws');

const PORT = process.env.PORT || 3000;

const app = express();
app.use(express.static(path.join(__dirname, 'public')));

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

// Distinct, vivid colors handed out round-robin so players can tell each other apart.
const COLORS = [
  0xff4d4d, 0x4dd2ff, 0x7dff4d, 0xffd24d,
  0xc04dff, 0xff8c1a, 0x4dffc3, 0xff4da6,
];
let nextId = 1;
let colorIdx = 0;

// id -> { ws, name, color, state }
const players = new Map();

function send(ws, msg) {
  if (ws.readyState === ws.OPEN) ws.send(JSON.stringify(msg));
}

function broadcast(msg, exceptId = null) {
  const data = JSON.stringify(msg);
  for (const [id, p] of players) {
    if (id !== exceptId && p.ws.readyState === p.ws.OPEN) p.ws.send(data);
  }
}

wss.on('connection', (ws) => {
  const id = nextId++;
  const color = COLORS[colorIdx++ % COLORS.length];
  let joined = false;

  ws.on('message', (raw) => {
    let msg;
    try {
      msg = JSON.parse(raw);
    } catch {
      return;
    }

    if (msg.t === 'join' && !joined) {
      joined = true;
      const name = String(msg.name || 'Skater').slice(0, 16) || 'Skater';
      players.set(id, { ws, name, color, state: null });

      // Tell the newcomer who they are and who is already here.
      const roster = [];
      for (const [pid, p] of players) {
        if (pid !== id) roster.push({ id: pid, name: p.name, color: p.color, state: p.state });
      }
      send(ws, { t: 'welcome', id, color, players: roster });
      broadcast({ t: 'joined', id, name, color }, id);
      console.log(`[+] ${name} (#${id}) joined — ${players.size} online`);
      return;
    }

    if (!joined) return;

    switch (msg.t) {
      case 'state': {
        const p = players.get(id);
        if (p) p.state = msg.s;
        broadcast({ t: 'state', id, s: msg.s }, id);
        break;
      }
      case 'trick':
        broadcast({ t: 'trick', id, name: msg.name, score: msg.score | 0 }, id);
        break;
      case 'chat': {
        const p = players.get(id);
        const text = String(msg.text || '').slice(0, 120).trim();
        if (p && text) broadcast({ t: 'chat', id, from: p.name, text });
        break;
      }
    }
  });

  ws.on('close', () => {
    const p = players.get(id);
    if (p) {
      players.delete(id);
      broadcast({ t: 'left', id });
      console.log(`[-] ${p.name} (#${id}) left — ${players.size} online`);
    }
  });

  ws.on('error', () => {});
});

server.listen(PORT, () => {
  console.log(`Skate park is open!`);
  console.log(`  Local:   http://localhost:${PORT}`);
  console.log(`  Friends on your network can join via your LAN IP, e.g. http://<your-ip>:${PORT}`);
});
